parts.text:
{
  "references": [
    {
      "id": "R1",
      "summary_ko": "초점이 맞춰진 금속 구조물의 패턴이 흔들리고 이동하는 것처럼 보임."
    },
    {
      "id": "R2",
      "summary_ko": "사람이 한쪽 손에만 장갑을 끼고 다른 쪽 손에는 아무것도 착용하지 않음."
    },
    {
      "id": "R3",
      "summary_ko": "남자가 나타나면서 마법처럼 두 손 모두 장갑을 끼고 있어 장갑이 갑자기 생겨남."
    },
    {
      "id": "R4",
      "summary_ko": "프롬프트와 달리 카메라 각도는 동일하게 유지되며 줌인과 줌아웃만 반복됨."
    },
    {
      "id": "R5",
      "summary_ko": "남자와 도구가 무작위로 갑자기 사라짐."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징과 픽셀 구조가 함께 변하여 형태나 존재 변화 가능성이 감지된 구간."
    },
    {
      "id": "C2",
      "summary_ko": "용접 도구를 든 작업자가 화면에서 사라진 후 다른 도구와 위치로 다시 나타남."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 구체적 대상이 없는 일반적인 측정 가설로, 패턴 변형 현상과의 연관성을 단정할 수 없습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 금속 구조물의 패턴 왜곡을 다루는 반면, C2는 작업자의 소멸 및 재등장을 다룹니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 대상이 특정되지 않은 일반 측정 가설이라 한쪽 손 장갑 착용 상태와의 관련성을 확정할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 장갑 착용 상태의 비대칭을 지적하지만, C2는 작업자의 소멸과 다른 도구로의 재등장을 설명합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 형태 및 존재 변화 가능성을 지칭하는 일반 가설로, 장갑이 갑자기 나타난 현상과의 일치 여부가 불분명합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R3는 장갑이 갑자기 나타난 현상을 다루며, C2는 작업자 전체가 사라졌다가 다른 도구를 들고 재등장하는 현상을 설명합니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 픽셀 및 영상 특징 변화 측정치에 불과하여 카메라 각도 및 줌 관련 설명과 동일한지 판단하기 어렵습니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R4는 카메라 각도 및 줌 동작에 관한 내용이고, C2는 작업자의 소멸과 재등장을 기술합니다."
    },
    {
      "reference_id": "R5",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 대상이 식별되지 않은 측정 가설로서 존재 변화를 언급하므로 관련 가능성이 있으나 텍스트만으로는 동일 사건 여부를 확정할 수 없습니다."
    },
    {
      "reference_id": "R5",
      "candidate_id": "C2",
      "verdict": "same",
      "reason_ko": "도구를 든 사람(작업자)이 화면에서 갑자기 사라지는 동일한 핵심 이상 현상을 공유합니다."
    }
  ]
}
